const RC_DUVIDAS=[['Quem precisa de jejum?','A ficha do exame mostra as horas de jejum. Em vários exames na mesma visita, vale o maior jejum.'],['Quanto tempo sai o resultado?','O prazo em dias úteis está na ficha. Urgência, quando existe, é em horas.'],['Posso tomar água em jejum?','Sim, água é liberada, salvo orientação do médico.'],['Como pedir exame de urgência?','Marque urgência no Novo atendimento. Nem todo exame aceita: veja na ficha.']];
function rcGeLista(){const G=RC.ge,q=semAc(G.q.trim());return Object.values(EX).filter(e=>e&&e.n&&(!q||semAc(e.n+' '+e.c+' '+(e.s||'')).includes(q))&&(!G.mat||(G.mat==='proc'?!!e.proc:e.m===G.mat))).sort((a,b)=>a.n.localeCompare(b.n))}
const rcPrazo=e=>e.proc?'No mesmo dia':!e.d?'Sob consulta':e.d===1?'1 dia útil':e.d+' dias úteis';
function rcGeRows(){const l=rcGeLista();if(!l.length)return vazioLinha(6,'Nenhum exame encontrado','Tente outro nome ou sinônimo.');
 return l.map(e=>`<tr style="cursor:pointer" onclick="rcGeVer('${e.c}')">${td('Exame',`<div class="two">${esc(e.n)}<small class="mono">${esc(e.c)}</small></div>`)}${td('Material',esc(e.m||e.proc||''))}${td('Preparo',esc(clPrepItem(e.c)||'Sem preparo'))}${td('Prazo',rcPrazo(e))}${td('Urgência',e.u?e.u+' h':'Não')}${td('Valor',fmt(e.p||0))}</tr>`).join('')}
function rcGeVer(c){const e=EX[c];if(!e)return;openDrawer(esc(e.n),kvs([['Código',`<span class="mono">${esc(e.c)}</span>`],['Também chamado',esc(e.s||'')],['Material',esc(e.m||'Não se aplica')],['Preparo',esc(clPrepItem(c)||'Sem preparo')],['Jejum',e.j?e.j+' horas':'Não precisa'],['Prazo',rcPrazo(e)],['Urgência',e.u?'Em até '+e.u+' h':'Não disponível'],['Valor particular',fmt(e.p||0)]])+`<div class="row" style="margin-top:12px"><button class="btn sec" onclick="closeDrawer();naNovo('orcamento')">Fazer orçamento</button></div>`)}
VIEWS['guia-exames']=()=>{rc();const G=RC.ge,mats=[...new Set(Object.values(EX).map(e=>e&&e.m).filter(Boolean))].sort();
 return `${pageHead('Recepção','Guia de Exames','Consulte preparo, material, prazo e valor para tirar dúvidas no balcão.')}
 ${rcTabs([['lista','Exames'],['duv','Dúvidas frequentes']],G.tab,'RC.ge.tab')}<div style="margin-top:12px">${G.tab==='duv'?`<div class="at-list">${RC_DUVIDAS.map(([q,r])=>`<div class="at-row"><div class="grow"><b>${q}</b><small>${r}</small></div></div>`).join('')}</div>`:`<div class="filters"><div class="inwrap" style="flex:1 1 240px">${LUPA}<input class="in" placeholder="Nome, sinônimo ou código" value="${esc(G.q)}" oninput="RC.ge.q=this.value;$('#rcGeB').innerHTML=rcGeRows()" aria-label="Buscar exame"></div><select class="in" style="width:auto" aria-label="Material" onchange="RC.ge.mat=this.value;$('#rcGeB').innerHTML=rcGeRows()"><option value="">Todos os materiais</option>${rcOpts(mats.map(m=>[m,m]),G.mat)}<option value="proc" ${G.mat==='proc'?'selected':''}>Consultas e procedimentos</option></select></div><div class="tablewrap"><table class="at-table"><thead><tr>${['Exame','Material','Preparo','Prazo','Urgência','Valor'].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody id="rcGeB">${rcGeRows()}</tbody></table></div>`}</div>`};

/* ---------- Configurações da recepção (notas 3, 4, 6 e 40) ---------- */
function rcTogLista(arr,v){const i=arr.indexOf(v);i>=0?arr.splice(i,1):arr.push(v);rcMudou()}
const rcCfgChips=(todos,sel,oc)=>`<div class="cl-jpick">${todos.map(([v,t])=>`<button type="button" class="chip ${sel.includes(v)?'on':''}" onclick="${oc.replace('#',v)}">${esc(t)}</button>`).join('')}</div>`;
function rcAddTipo(){const n=$('#cfT').value.trim(),p=$('#cfTP').value.trim().toUpperCase();if(!n||!p){toast('Informe nome e prefixo','warn');return}if(RC.cfg.tipos.some(t=>t.pref===p)){toast('Prefixo já usado','warn');return}RC.cfg.tipos.push({id:p,n,pref:p,ativo:true,unids:[RC.unid]});RC.cfg.guiches.forEach(g=>{if(g.unid===RC.unid)g.tipos.push(p)});rcMudou();toast('Tipo de senha criado')}
function rcAddPeso(){const n=$('#cfP').value.trim(),l=$('#cfPL').value.trim().toUpperCase(),v=+$('#cfPV').value;if(!n||!l||!v){toast('Informe nome, letra e valor','warn');return}if(RC.cfg.pesos.some(p=>p.letra===l)){toast('Letra já usada','warn');return}const id='P'+(++RC.seqId);RC.cfg.pesos.push({id,n,letra:l,valor:v,cor:'neutral',ativo:true});RC.cfg.guiches.forEach(g=>g.pesos.push(id));rcMudou();toast('Peso criado')}
function rcAddGuiche(){const q=rcGuiches().length+1;RC.cfg.guiches.push({id:'g'+(++RC.seqId),n:'Guichê '+q,op:'',unid:RC.unid,ativo:true,tipos:RC.cfg.tipos.map(t=>t.id),pesos:RC.cfg.pesos.map(p=>p.id)});rcMudou();toast(`Guichê ${q} criado`)}
function rcAddSetor(){const n=$('#cfS').value.trim();if(!n){toast('Informe o nome do setor','warn');return}RC.cfg.setores.push({id:'s'+(++RC.seqId),n,grupos:[],locais:[n],perfis:[]});rcMudou();toast('Setor criado')}
function rcSetGrupo(id,g){const s=rcSetor(id);if(s.grupos.includes(g))s.grupos=s.grupos.filter(x=>x!==g);else{RC.cfg.setores.forEach(o=>o.grupos=o.grupos.filter(x=>x!==g));s.grupos.push(g)}rcMudou()}
function rcSeqPreset(k){RC.cfg.seq={a:['NOR','PRI'],b:['PRI','PRI','JEJ'],c:['ESP','PRI','NOR','PRI','JEJ','NOR']}[k];RC.ptr=0;rcMudou();toast('Sequência aplicada')}
const rcSeqPrevia=()=>{const dem=RC.cfg.pesos.filter(p=>p.ativo).flatMap(p=>[0,1,2].map(i=>({peso:p.id,ts:i}))).filter(x=>!RC.cfg.pesos.find(p=>p.id===x.peso).sempre);return rcOrdem(dem,RC.cfg,0).slice(0,8).map(x=>rcPeso(x.peso).n).join(' · ')};
