 P('Joana Darc Pereira','A-085','NOR',19,'atendimento',{local:'Guichê 3',hIni:rcH(Date.now()-300000)});
 P('Ana Souza','A-080','NOR',60,'finalizada',{hFim:rcH(Date.now()-1800000),nps:{h:'08:10',nota:'9'}});
 P('Marta Lima','P-003','PRI',12,'cancelada',{motivo:'Gerada por engano',hFim:rcH(Date.now()-600000)});
